BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Panther Peptides Command Center</title><style>:root{--bg:#050b13;--panel:#0b1727;--line:#203c59;--text:#f2f7fc;--muted:#8ea8c1;--green:#39d49d;--amber:#f2b84b;--red:#ff7185}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#17375c 0,#07111f 35%,#040910 100%);color:var(--text);font:15px system-ui,-apple-system,sans-serif;min-height:100vh}.wrap{max-width:1540px;margin:auto;padding:22px}.top,.head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:14px}.logo{width:46px;height:46px;border-radius:14px;background:linear-gradient(135deg,#3f91ff,#53dfc0);display:grid;place-items:center;font-weight:900;color:#06101d}.brand h1,.card h2{margin:0}.brand small,.muted,.notice{color:var(--muted)}.nav,.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #2d4c6c;background:#10223a;color:#eaf4ff;padding:10px 13px;border-radius:11px;font-weight:750;cursor:pointer;text-decoration:none}.btn.green{background:#123c33;border-color:#236d59;color:#c9f8e7}.btn.amber{background:#3b2c10;border-color:#775b20;color:#ffe0a0}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4;padding:11px 15px;border-radius:13px;margin-bottom:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.metric,.card{background:linear-gradient(180deg,rgba(15,32,53,.98),rgba(9,22,38,.98));border:1px solid var(--line);border-radius:18px}.metric{padding:17px}.metric b{display:block;font-size:27px;margin-top:6px}.metric span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.7fr);gap:18px}.card{padding:20px}.tablewrap{overflow:auto;border:1px solid #1f3852;border-radius:14px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:12px;border-bottom:1px solid #1d354e;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#91acc6;background:#0a1727}td{color:#e8f1fa}.pill{display:inline-block;border:1px solid #31516f;border-radius:999px;padding:5px 9px;font-size:12px}.pill.available,.pill.released,.pill.approved,.pill.on_file{color:#bdf5df;border-color:#286b59;background:#0d2b24}.pill.quarantine,.pill.hold,.pill.blocked{color:#ffd278;border-color:#76591e;background:#2b210d}.drop{border:1px dashed #3a6082;border-radius:12px;padding:9px;background:#081522}.stack{display:flex;flex-direction:column;gap:12px}.event{padding:12px;border:1px solid #203b57;border-radius:13px;background:#091725}.event b{display:block}.event small{color:var(--muted)}.empty{padding:36px;text-align:center;color:var(--muted)}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.wrap{padding:12px}}</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">PP</div><div><h1>Panther Peptides Command Center</h1><small>Jarvis Business Operations</small></div></div><div class="nav"><a class="btn" href="/">Jarvis</a><button class="btn" onclick="load()">Refresh</button></div></div><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Received inventory is available by default. Documentation is tracked independently; you can place any lot on hold or in quarantine at any time.</div><div class="metrics"><div class="metric"><span>Inventory lots</span><b id="lots">—</b></div><div class="metric"><span>Total units</span><b id="units">—</b></div><div class="metric"><span>Held / quarantined</span><b id="quarantine">—</b></div><div class="metric"><span>Available units</span><b id="released">—</b></div><div class="metric"><span>Lots needing documents</span><b id="missing">—</b></div></div><div class="grid"><section class="card"><div class="head"><div><h2>Inventory</h2><div class="notice">Availability and documentation are independent controls.</div></div><button class="btn" onclick="importLegacy()">Recover legacy inventory</button></div><div class="tablewrap"><table><thead><tr><th>Product</th><th>Lot / SKU</th><th>Qty</th><th>Availability</th><th>Documentation</th><th>Actions</th></tr></thead><tbody id="inventory"></tbody></table></div></section><aside class="stack"><section class="card"><h2>Jarvis Operations</h2><p id="runtime" class="notice">Loading…</p><div id="objectives"></div></section><section class="card"><h2>Business Activity</h2><div id="events"></div></section></aside></div></div><script>const $=id=>document.getElementById(id);let data;async function api(url,opt={}){const r=await fetch(url,{...opt,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401){location.href='/';throw Error('Owner login required')}if(!r.ok)throw Error(d.detail||d.error||`HTTP ${r.status}`);return d}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pill(s){return `<span class="pill ${esc(String(s).toLowerCase())}">${esc(s)}</span>`}async function load(){try{data=await api('/business/dashboard');let s=data.summary;$('lots').textContent=s.lots;$('units').textContent=s.units;$('quarantine').textContent=s.quarantined_units;$('released').textContent=s.released_units;$('missing').textContent=s.lots_missing_or_unknown_docs;renderInventory();renderOps();renderEvents()}catch(e){console.error(e)}}function renderInventory(){let rows=data.inventory||[];$('inventory').innerHTML=rows.length?rows.map(x=>{let docs=(x.documents||[]).map(d=>`<div>${esc(d.original_name)} ${pill(d.review_status)}</div>`).join('');let controls=x.legacy?'<span class="muted">Import to manage this record.</span>':`<div class="actions"><button class="btn green" onclick="setStatus(${x.id},'available')">Available</button><button class="btn amber" onclick="setStatus(${x.id},'hold')">Hold</button><button class="btn amber" onclick="setStatus(${x.id},'quarantine')">Quarantine</button></div><form class="drop" onsubmit="upload(event,${x.id})"><input type="file" required accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.txt"><button class="btn" type="submit">Upload document</button></form>${docs}`;return `<tr><td><b>${esc(x.product)}</b><br><span class="muted">${esc(x.vial_size||'')}</span></td><td>${esc(x.lot_code||'—')}<br><span class="muted">${esc(x.sku||'')}</span></td><td>${esc(x.quantity)}</td><td>${pill(x.status)}</td><td>${pill(x.coa_status||'unknown')}</td><td>${controls}</td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty">No inventory records visible. Recover legacy inventory to scan the persistent database.</div></td></tr>`}function renderOps(){let o=data.objectives||[];$('runtime').textContent=`${o.filter(x=>['running','queued'].includes(x.state)).length} active / queued · ${o.filter(x=>x.state==='blocked').length} blocked`;$('objectives').innerHTML=o.slice(0,6).map(x=>`<div class="event"><b>#${x.id} ${esc(x.title)}</b><small>${esc(x.state)} · step ${esc(x.step)}/${esc(x.max_steps)}</small></div>`).join('')||'<p class="notice">No active objectives.</p>'}function renderEvents(){$('events').innerHTML=(data.events||[]).slice(0,8).map(e=>`<div class="event"><b>${esc(e.title)}</b><div>${esc(e.detail||'')}</div><small>${esc(e.created_at)}</small></div>`).join('')||'<p class="notice">No business events yet.</p>'}async function importLegacy(){if(!confirm('Recover discoverable inventory from the existing Jarvis database? Existing data will not be deleted.'))return;let d=await api('/business/inventory/import-legacy',{method:'POST'});alert(`Imported ${d.imported} record(s).`);load()}async function upload(ev,id){ev.preventDefault();let f=ev.target.querySelector('input[type=file]').files[0],fd=new FormData();fd.append('file',f);fd.append('kind','coa');let r=await fetch(`/business/inventory/${id}/documents`,{method:'POST',body:fd}),d=await r.json();if(!r.ok)return alert(d.detail||'Upload failed');load()}async function setStatus(id,status){if(!confirm(`Change this lot to ${status}?`))return;try{await api(`/business/inventory/${id}/status`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status})});load()}catch(e){alert(e.message)}}load();setInterval(load,12000)</script></body></html>'''